PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'pcs', sale_price_paisa INTEGER NOT NULL DEFAULT 0 CHECK(sale_price_paisa>=0), avg_cost_paisa INTEGER NOT NULL DEFAULT 0 CHECK(avg_cost_paisa>=0), stock_qty_milli INTEGER NOT NULL DEFAULT 0, min_stock_qty_milli INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, notes TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, notes TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, ref_no TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN('opening_cash','sale_items','sale_total','purchase','customer_collection','supplier_payment','expense','cash_in','cash_out','stock_adjustment','sale_return','purchase_return','correction')), occurred_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), amount_paisa INTEGER NOT NULL DEFAULT 0 CHECK(amount_paisa>=0), cash_delta_paisa INTEGER NOT NULL DEFAULT 0, customer_id TEXT REFERENCES customers(id), supplier_id TEXT REFERENCES suppliers(id), note TEXT, status TEXT NOT NULL DEFAULT 'posted' CHECK(status IN('posted','reversed')), idempotency_key TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS transaction_items (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id), product_id TEXT NOT NULL REFERENCES products(id), qty_milli INTEGER NOT NULL CHECK(qty_milli>0), unit_price_paisa INTEGER NOT NULL CHECK(unit_price_paisa>=0), unit_cost_paisa INTEGER NOT NULL CHECK(unit_cost_paisa>=0), line_total_paisa INTEGER NOT NULL CHECK(line_total_paisa>=0), line_cost_paisa INTEGER NOT NULL CHECK(line_cost_paisa>=0));
CREATE TABLE IF NOT EXISTS cash_ledger (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL UNIQUE REFERENCES transactions(id), direction TEXT NOT NULL CHECK(direction IN('in','out')), amount_paisa INTEGER NOT NULL CHECK(amount_paisa>0), category TEXT NOT NULL, occurred_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), note TEXT);
CREATE TABLE IF NOT EXISTS stock_movements (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id), product_id TEXT NOT NULL REFERENCES products(id), qty_delta_milli INTEGER NOT NULL, unit_cost_paisa INTEGER NOT NULL CHECK(unit_cost_paisa>=0), reason TEXT NOT NULL, occurred_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS customer_ledger (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id), customer_id TEXT NOT NULL REFERENCES customers(id), debit_paisa INTEGER NOT NULL DEFAULT 0 CHECK(debit_paisa>=0), credit_paisa INTEGER NOT NULL DEFAULT 0 CHECK(credit_paisa>=0), note TEXT, occurred_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS supplier_ledger (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id), supplier_id TEXT NOT NULL REFERENCES suppliers(id), debit_paisa INTEGER NOT NULL DEFAULT 0 CHECK(debit_paisa>=0), credit_paisa INTEGER NOT NULL DEFAULT 0 CHECK(credit_paisa>=0), note TEXT, occurred_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS stock_counts (id TEXT PRIMARY KEY, ref_no TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','counted','closed')), note TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), closed_at TEXT);
CREATE TABLE IF NOT EXISTS stock_count_items (id TEXT PRIMARY KEY, stock_count_id TEXT NOT NULL REFERENCES stock_counts(id), product_id TEXT NOT NULL REFERENCES products(id), system_qty_milli INTEGER NOT NULL, physical_qty_milli INTEGER, unit_cost_paisa INTEGER NOT NULL DEFAULT 0, UNIQUE(stock_count_id,product_id));
CREATE TABLE IF NOT EXISTS stock_adjustments (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL UNIQUE REFERENCES transactions(id), product_id TEXT NOT NULL REFERENCES products(id), qty_delta_milli INTEGER NOT NULL, reason TEXT NOT NULL, unit_cost_paisa INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL UNIQUE REFERENCES transactions(id), category TEXT NOT NULL, amount_paisa INTEGER NOT NULL CHECK(amount_paisa>0), is_owner_draw INTEGER NOT NULL DEFAULT 0 CHECK(is_owner_draw IN(0,1)), note TEXT);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT, actor TEXT NOT NULL DEFAULT 'owner', created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);
CREATE INDEX IF NOT EXISTS idx_transactions_date ON transactions(occurred_at);
CREATE INDEX IF NOT EXISTS idx_transactions_kind ON transactions(kind,status);
CREATE INDEX IF NOT EXISTS idx_customer_ledger_customer_date ON customer_ledger(customer_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_supplier_ledger_supplier_date ON supplier_ledger(supplier_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_stock_movements_product_date ON stock_movements(product_id,occurred_at);
